(()=>{'use strict';const $=id=>document.getElementById(id);const btn=$('retry');function cleanDate(v){if(!v)return 'DATE NOT VERIFIED';const d=new Date(v);return Number.isFinite(d.valueOf())?d.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short',timeZone:'UTC'})+' UTC':'DATE NOT VERIFIED';}async function load(){btn.disabled=true;$('status').textContent='Checking tropical weather sources…';$('summary').textContent='Preparing the briefing…';$('headlines').replaceChildren();try{const res=await fetch('/api/news/daily',{headers:{'Accept':'application/json'},cache:'no-store'});if(!res.ok)throw Error('HTTP '+res.status);const data=await res.json();$('date').textContent=(data.date_utc||'')+' UTC';const diag=$('feedDiagnostics');const statuses=Array.isArray(data.feed_status)?data.feed_status:[];diag.hidden=!statuses.length;diag.replaceChildren();if(statuses.length){const details=document.createElement('details'),sum=document.createElement('summary'),ul=document.createElement('ul');sum.textContent='SOURCE STATUS · '+statuses.filter(s=>s.status==='ok').length+' / '+statuses.length+' RSS feeds reporting';details.append(sum);for(const st of statuses){const li=document.createElement('li');li.textContent=st.source+': '+(st.status==='ok'?st.count+' recent item(s)':st.status==='no_recent_items'?'reachable, no recent items':'unavailable'+(st.reason?' ('+st.reason+')':''));ul.append(li)}details.append(ul);diag.append(details)}$('summary').textContent=data.summary||('AI briefing unavailable: '+(data.summary_note||'Please retry.'));const articles=Array.isArray(data.headlines)?data.headlines:[];$('status').textContent=data.summary_method==='web_search_fallback'?'WEB-SOURCED AI BRIEFING · RSS UNAVAILABLE':articles.length?'LATEST BRIEFING · '+articles.length+' SOURCE LINKS':data.source_status==='sources_unreachable'?'RSS news feeds unavailable. See source status and AI diagnostic below.':'No recent RSS headlines available.';$('count').textContent=articles.length+' SOURCES · RECENT COVERAGE';for(const [i,item] of articles.entries()){const li=document.createElement('li'),wrap=document.createElement('div'),link=document.createElement('a'),meta=document.createElement('div');if(!/^https:\/\//.test(item.url||''))continue;link.href=item.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent=item.title;meta.className='meta';meta.textContent=item.channel+' · '+cleanDate(item.published_utc)+' · SOURCE '+(i+1);wrap.append(link,meta);li.append(wrap);$('headlines').append(li)}if(!articles.length){const li=document.createElement('li');li.textContent='No independently sourced articles are available right now.';$('headlines').append(li)}}catch(e){$('status').textContent='Briefing request failed ('+e.message+').';$('summary').textContent='Unable to retrieve the briefing from the STORMWATCH backend. Check /api/health and redeploy.'}finally{btn.disabled=false}}btn.addEventListener('click',load);load()})();